import zipfile, sys, hashlib, io

SRC = r"C:/Users/leigh/OneDrive/Documents/Dev/minecraft-datapacks/OneBlockLastStanding/OneBlockLastStanding.zip"
OUT = r"C:/Users/leigh/OneDrive/Documents/Dev/_build/obls_report.txt"

out = io.StringIO()
def p(*a):
    print(*a, file=out)

z = zipfile.ZipFile(SRC)
names = z.namelist()
p("TOTAL_MEMBERS", len(names))
roots = {}
for n in names:
    top = n.split("/")[0]
    roots[top] = roots.get(top, 0) + 1
p("ROOT_ENTRIES", roots)
p("HAS_root_pack.mcmeta", "pack.mcmeta" in names)
p("HAS_root_data_prefix", any(n.startswith("data/") for n in names))
p("HAS_macosx", sum(1 for n in names if n.startswith("__MACOSX")))
p("HAS_nested_zip", [n for n in names if n.endswith(".zip")])
p("DIR_ENTRIES", [n for n in names if n.endswith("/")][:10])
p("---------- member list ----------")
for n in sorted(names):
    if n.endswith("/"):
        continue
    if n.startswith("__MACOSX"):
        continue
    i = z.getinfo(n)
    p("%8d  %s" % (i.file_size, n))
p("---------- md5 of duplicate basenames ----------")
seen = {}
for n in names:
    if n.endswith("/") or n.startswith("__MACOSX"):
        continue
    rel = n.split("/")[-1]
    seen.setdefault(rel, []).append(n)
for rel, lst in seen.items():
    if len(lst) > 1:
        hashes = {}
        for m in lst:
            d = z.read(m)
            hashes[hashlib.md5(d).hexdigest()[:10]] = hashes.get(hashlib.md5(d).hexdigest()[:10], []) + [m]
        p(rel, "variants=", len(hashes), {k: v for k, v in hashes.items()} if len(hashes) > 1 else "identical")
p("---------- pack.mcmeta ----------")
for cand in names:
    if cand.endswith("pack.mcmeta"):
        p("###", cand)
        p(z.read(cand).decode("utf-8", "replace"))
p("---------- tags ----------")
for cand in names:
    if "/tags/" in cand and cand.endswith(".json"):
        p("###", cand)
        p(z.read(cand).decode("utf-8", "replace"))
p("---------- oneblock functions ----------")
for cand in sorted(names):
    if cand.endswith(".mcfunction") and "oneblock" in cand and not cand.startswith("__MACOSX"):
        p("###", cand)
        txt = z.read(cand).decode("utf-8", "replace")
        for idx, line in enumerate(txt.replace("\r\n", "\n").split("\n"), 1):
            p("%4d| %s" % (idx, line))
p("---------- ija key files ----------")
for cand in sorted(names):
    if not cand.endswith(".mcfunction") or "__MACOSX" in cand:
        continue
    base = cand.split("/")[-1]
    if base in ("on-join.mcfunction", "on-load.mcfunction", "respawn.mcfunction", "spawn.mcfunction", "handle-triggers.mcfunction", "loop.mcfunction", "main.mcfunction", "portal-respawn.mcfunction", "show-death-message.mcfunction"):
        p("###", cand)
        txt = z.read(cand).decode("utf-8", "replace")
        for idx, line in enumerate(txt.replace("\r\n", "\n").split("\n"), 1):
            p("%4d| %s" % (idx, line))

with open(OUT, "w", encoding="utf-8", newline="\n") as f:
    f.write(out.getvalue())
print("WROTE", OUT, len(out.getvalue()), "bytes")

