import re
# inventory: functions by namespace
funcs = {}  # 'ns:path' -> member
for n in names:
    m = re.match(r'^data/([^/]+)/function/(.+)\.mcfunction$', n)
    if m:
        funcs[f"{m.group(1)}:{m.group(2)}"] = n
print("functions:", len(funcs))

# tags
tag_refs = []  # (tagfile, ref)
for n in names:
    m = re.match(r'^data/([^/]+)/tags/function/(.+)\.json$', n)
    if m:
        data = json.loads(z.read(n).decode('utf-8-sig'))
        for ref in data.get('values', []):
            tag_refs.append((n, ref))
print("tag refs:", len(tag_refs))
missing = [(t, r) for t, r in tag_refs if r.lstrip('#') not in funcs and not r.startswith('#')]
print("MISSING tag targets:", missing)
for t, r in tag_refs:
    print("  ", t.split('tags/function/')[0].split('/')[1], "tags", r)

# call graph: every 'function ns:path' invocation
invocations = {}  # caller -> set(refs)
undangled = {}
CALL = re.compile(r'function\s+([a-z0-9_.\-]+):([a-z0-9_/\.\-]+)')
for fid, member in funcs.items():
    txt = z.read(member).decode('utf-8', 'replace').replace('\r\n','\n')
    refs = set()
    for line in txt.split('\n'):
        line = line.split('#')[0]
        for m in CALL.finditer(line):
            refs.add(f"{m.group(1)}:{m.group(2)}")
    invocations[fid] = refs
    for r in refs:
        if r not in funcs:
            undangled.setdefault(fid, set()).add(r)
print("callers:", len(invocations))
total_missing = sum(len(v) for v in undangled.values())
print("DANGLING function calls:", total_missing)
for fid, rs in sorted(undangled.items()):
    for r in sorted(rs):
        print(f"  {fid} -> {r}  MISSING")

created = set()   # objective names
uses = {}         # obj -> [(caller, line)]
ADD = re.compile(r'scoreboard\s+objectives\s+add\s+(\S+)')
USE = re.compile(r'scoreboard\s+(?:players\s+(?:list|set|add|remove|get|reset|enable|operation|random|test)\b[^\n]*?|objectives\s+(?:setdisplay|modify)\b[^\n]*?)\s+([A-Za-z0-9_.+-]+)')
# simpler: capture objective token in any scoreboard players/op line
def scan(fid, member):
    txt = z.read(member).decode('utf-8','replace').replace('\r\n','\n')
    for i, line in enumerate(txt.split('\n'), 1):
        l = line.split('#')[0]
        m = ADD.search(l)
        if m:
            created.add(m.group(1))
        # objective used as last-ish arg of 'scoreboard players ... <obj>'
        m2 = re.search(r'scoreboard players\s+(?:set|add|remove|get|reset|enable|operation|random|test)\s+(.*)', l)
        if m2:
            rest = m2.group(1).split()
            if m2.group(1).strip().startswith('operation'):
                # operation <t> <tobj> <op> <s> <sobj>
                if len(rest) >= 5:
                    for o in (rest[1], rest[4]):
                        uses.setdefault(o, []).append((fid, i, l.strip()))
            else:
                if len(rest) >= 2:
                    uses.setdefault(rest[1], []).append((fid, i, l.strip()))
        # predicates/criteria like minecraft.custom:minecraft.leave_game in objectives add handled above
for fid, member in funcs.items():
    scan(fid, member)
print("objectives created:", sorted(created))
uncreated = sorted(set(uses) - created)
print("objectives USED but never added:", uncreated)
for o in uncreated:
    for fid, i, l in uses[o][:4]:
        print(f"  {o} <- {fid}:{i}  {l[:110]}")
print("total use sites:", sum(len(v) for v in uses.values()))

loot = set()
for n in names:
    m = re.match(r'^data/([^/]+)/loot_table/(.+)\.json$', n)
    if m:
        loot.add(f"{m.group(1)}:{m.group(2)}")
print("loot tables:", len(loot))
LOOTREF = re.compile(r'loot\s+([a-z0-9_.\-]+):([a-z0-9_/\.\-]+)')
miss_loot = []
for fid, member in funcs.items():
    txt = z.read(member).decode('utf-8','replace')
    for i, line in enumerate(txt.replace('\r\n','\n').split('\n'), 1):
        l = line.split('#')[0]
        for m in re.finditer(r'\bloot\s+(?:give|insert|replace|spawn|modify)\b', l):
            mm = re.search(r'loot\s+([a-z0-9_.\-]+:[a-z0-9_/\.\-]+)', l[m.end()-4:])
        # simpler: find 'loot ns:path' where ns:path follows keywords
        for mm in re.finditer(r'(?:give|insert|replace|spawn)\s+.*?\sloot\s+([a-z0-9_.\-]+:[a-z0-9_/\.\-]+)', l):
            ref = mm.group(1)
            if ref not in loot:
                miss_loot.append((fid, i, ref, l.strip()[:100]))
print("MISSING loot refs:", len(miss_loot))
for x in miss_loot[:20]: print("  ", x)

# line-level lint: unbalanced quotes/braces, trailing garbage
lint = []
for fid, member in funcs.items():
    txt = z.read(member).decode('utf-8','replace').replace('\r\n','\n')
    for i, line in enumerate(txt.split('\n'), 1):
        l = line.split('#')[0]
        if not l.strip(): continue
        if l.count('"') % 2: lint.append((fid,i,"odd quotes",line.strip()[:100]))
        if l.count('{') != l.count('}'): lint.append((fid,i,"brace mismatch",line.strip()[:100]))
        if l.count('[') != l.count(']'): lint.append((fid,i,"bracket mismatch",line.strip()[:100]))
        if re.search(r'\bexecute\s+$', l) or l.strip().endswith(('run','if','unless','at','as','positioned','in','on','store','anchored','facing','align','rotated','summon')):
            lint.append((fid,i,"dangling clause",line.strip()[:100]))
print("lint hits:", len(lint))
for x in lint[:30]: print("  ", x)

# known-bad patterns
gamerules = set()
badpat = []
for fid, member in funcs.items():
    txt = z.read(member).decode('utf-8','replace').replace('\r\n','\n')
    for i, line in enumerate(txt.split('\n'),1):
        l = line.split('#')[0]
        m = re.search(r'gamerule\s+(\S+)', l)
        if m: gamerules.add((m.group(1), fid))
        if 'keep_inventory' in l: badpat.append((fid,i,'snake_case gamerule',line.strip()[:100]))
        if re.search(r'scoreboard players (?:set|add|get|remove|reset|enable|operation).*\sob\.tmp\b', l) and False: pass
print("gamerules used:", gamerules)
print("bad patterns:", badpat)

# data storage objectives: 'data (get|modify|merge) storage ns:path' vs any creation
storage_set = set(); storage_use = {}
for fid, member in funcs.items():
    txt = z.read(member).decode('utf-8','replace').replace('\r\n','\n')
    for i, line in enumerate(txt.split('\n'),1):
        l = line.split('#')[0]
        m = re.search(r'storage\s+([a-z0-9_.\-]+:[a-z0-9_/\.\-]+)', l)
        if m:
            if re.search(r'data\s+(?:modify|merge)\s+storage', l):
                storage_set.add(m.group(1).split(':')[0])
            storage_use.setdefault(m.group(1), []).append((fid,i))
print("storages referenced:", sorted(storage_use))
print("storage namespaces written:", sorted(storage_set))

# summon entity types validity (basic check against known id charset + suspicious names)
ents = set()
for fid, member in funcs.items():
    txt = z.read(member).decode('utf-8','replace')
    for m in re.finditer(r'summon\s+([a-z0-9_.\-]+:[a-z0-9_/]+)', txt):
        ents.add(m.group(1))
print("entity types summoned:", sorted(ents))

# effect/potion ids, advancement refs
adv = set()
for fid, member in funcs.items():
    txt = z.read(member).decode('utf-8','replace')
    for m in re.finditer(r'advancement\s+(?:grant|revoke)\s+\S+\s+(?:only|through|from|everything)\s+([a-z0-9_.\-]+:[a-z0-9_/\.\-]+)', txt):
        adv.add(m.group(1))
adv_exist = set()
for n in names:
    m = re.match(r'^data/([^/]+)/advancement/(.+)\.json$', n)
    if m: adv_exist.add(f"{m.group(1)}:{m.group(2)}")
print("advancements referenced:", sorted(adv))
print("MISSING advancements:", sorted(adv - adv_exist))

# predicates referenced
pred_ref = set()
for fid, member in funcs.items():
    txt = z.read(member).decode('utf-8','replace')
    for m in re.finditer(r'\bpredicate\s+([a-z0-9_.\-]+:[a-z0-9_/\.\-]+)', txt):
        pred_ref.add(m.group(1))
pred_exist = set()
for n in names:
    m = re.match(r'^data/([^/]+)/predicate/(.+)\.json$', n)
    if m: pred_exist.add(f"{m.group(1)}:{m.group(2)}")
print("predicates referenced:", sorted(pred_ref))
print("MISSING predicates:", sorted(pred_ref - pred_exist))

# item/blocks: setblock/fill block ids sanity (namespace charset)
blk = set()
for fid, member in funcs.items():
    txt = z.read(member).decode('utf-8','replace')
    for m in re.finditer(r'(?:setblock|fill|clone)\s+~?\S*\s+~?\S*\s+~?\S*\s+([a-z0-9_.\-]+:[a-z0-9_/]+|[a-z0-9_]+)', txt):
        blk.add(m.group(1))
print("block ids (sample):", sorted(blk)[:40])

# Known risk #5: admin/menu phase-skip vs renumbered counters.
# Find all references to phase numbers/counters and compare generated phase files.
import collections
counters = collections.Counter()
for fid, member in funcs.items():
    txt = z.read(member).decode('utf-8','replace').replace('\r\n','\n')
    for line in txt.split('\n'):
        l = line.split('#')[0]
        for m in re.finditer(r'#([a-z_]+)\s+ob\.[a-z]+\s(?:matches|=|<|>|>=|<=)\s*(\d+)', l):
            counters[(m.group(1))]+=1
print("score-holder #name match usage:", dict(counters))

# 'set' values of counters named in spec: ob.state machine states
states = collections.Counter()
for fid, member in funcs.items():
    txt = z.read(member).decode('utf-8','replace').replace('\r\n','\n')
    for line in txt.split('\n'):
        l = line.split('#')[0]
        for m in re.finditer(r'scoreboard players (?:set|add)\s+(\S+)\s+(ob\.\w+)\s+(-?\d+)', l):
            states[(m.group(2), m.group(1), m.group(3))] += 1
for k, v in sorted(states.items()):
    print(k, v)

