"""Static audit of OneBlockLastStanding.zip — structural + cross-reference validation."""
import zipfile, json, re, sys, collections, io

ZIP = r"minecraft-datapacks/OneBlockLastStanding/OneBlockLastStanding.zip"
out = io.StringIO()
def p(*a): print(*a, file=out)

z = zipfile.ZipFile(ZIP)
raw_names = z.namelist()
names = [n for n in raw_names if not n.endswith('/') and not n.startswith('__MACOSX')]
p("== ARCHIVE ==")
p("members:", len(raw_names), "(files:", len(names), ")")
p("testzip bad entry:", z.testzip())
p("root pack.mcmeta:", 'pack.mcmeta' in names)
p("stray top-level entries:", sorted({n.split('/')[0] for n in names} - {'pack.mcmeta','data','README.md','NOTICE.md'}))

# ---------- inventory ----------
funcs = {}   # 'ns:path' -> member
for n in names:
    m = re.match(r'^data/([^/]+)/function/(.+)\.mcfunction$', n)
    if m: funcs[f"{m.group(1)}:{m.group(2)}"] = n
loot = {f"{m.group(1)}:{m.group(2)}" for n in names
        if (m := re.match(r'^data/([^/]+)/loot_table/(.+)\.json$', n))}
adv_exist = {f"{m.group(1)}:{m.group(2)}" for n in names
        if (m := re.match(r'^data/([^/]+)/advancement[s]?/(.+)\.json$', n))}
pred_exist = {f"{m.group(1)}:{m.group(2)}" for n in names
        if (m := re.match(r'^data/([^/]+)/predicate/(.+)\.json$', n))}
item_mods = {f"{m.group(1)}:{m.group(2)}" for n in names
        if (m := re.match(r'^data/([^/]+)/item_modifier/(.+)\.json$', n))}
p("functions:", len(funcs), " loot tables:", len(loot), " advancements:", len(adv_exist),
  " predicates:", len(pred_exist), " item_modifiers:", len(item_mods))

def text(member):
    return z.read(member).decode('utf-8', 'replace').replace('\r\n', '\n')

def code_lines(fid):
    for i, line in enumerate(text(funcs[fid]).split('\n'), 1):
        yield i, line.split('#')[0].rstrip()

# ---------- JSON validity ----------
p("\n== JSON VALIDITY ==")
json_err = []
for n in names:
    if n.endswith('.json') or n.endswith('.mcmeta'):
        try: json.loads(z.read(n).decode('utf-8-sig'))
        except Exception as e: json_err.append((n, str(e)))
p("json files with parse errors:", len(json_err))
for n, e in json_err: p("  JSON ERR:", n, "|", e[:150])

# ---------- tags ----------
p("\n== TAG RESOLUTION ==")
tag_bad = 0
for n in names:
    m = re.match(r'^data/([^/]+)/tags/function/(.+)\.json$', n)
    if not m: continue
    ns = m.group(1)
    data = json.loads(z.read(n).decode('utf-8-sig'))
    for ref in data.get('values', []):
        if ref.startswith('#'):   # nested tag ref
            tns, _, tpath = ref[1:].partition(':')
            target = f"data/{tns}/tags/function/{tpath}.json"
            ok = target in names
        else:
            ok = ref in funcs
        if not ok:
            tag_bad += 1
            p("  TAG MISSING:", n, "->", ref)
p("unresolved tag entries:", tag_bad)

# ---------- function call graph ----------
p("\n== FUNCTION CALLS ==")
CALL = re.compile(r'\bfunction\s+([a-z0-9_.\-]+):([a-z0-9_/.\-]+)')
dangling = collections.defaultdict(set)
call_count = 0
for fid in funcs:
    for i, l in code_lines(fid):
        for m in CALL.finditer(l):
            call_count += 1
            ref = f"{m.group(1)}:{m.group(2)}"
            if ref not in funcs:
                dangling[fid].add((ref, i))
p("total call sites:", call_count)
p("dangling calls:", sum(len(v) for v in dangling.values()))
for fid, rs in sorted(dangling.items()):
    for ref, i in sorted(rs): p(f"  {fid}:{i} -> {ref} MISSING")

# ---------- scoreboard objectives ----------
p("\n== SCOREBOARD OBJECTIVES ==")
created = set()
add_sites = {}   # obj -> (fid, line)
uses = collections.defaultdict(list)
for fid in funcs:
    for i, l in code_lines(fid):
        m = re.search(r'\bscoreboard\s+objectives\s+add\s+(\S+)', l)
        if m:
            created.add(m.group(1)); add_sites.setdefault(m.group(1), (fid, i, l.strip()))
        m = re.search(r'\bscoreboard\s+players\s+(set|add|remove|get|reset|enable|operation|random|test)\s+(.*)', l)
        if m:
            rest = m.group(2).split()
            if m.group(1) == 'operation':
                if len(rest) >= 5:
                    for o in (rest[1], rest[4]): uses[o].append((fid, i, l.strip()))
            elif len(rest) >= 2:
                uses[rest[1]].append((fid, i, l.strip()))
        # objective add criteria sanity is captured above; also objectives setdisplay/modify
        m = re.search(r'\bscoreboard\s+objectives\s+(setdisplay|modify)\s+(\S+)', l)
        if m: uses[m.group(2)].append((fid, i, l.strip()))
p("objectives created:", sorted(created))
missing_objs = sorted(set(uses) - created)
p("objectives used but NEVER added:", missing_objs)
for o in missing_objs:
    for fid, i, l in uses[o][:3]: p(f"  {o} <- {fid}:{i} | {l[:120]}")

# scoreboards in tick that reference objectives added only in load: note, not an error per se (load runs first)
# but flag objectives referenced in files that are NOT behind load ordering — informational only.

# ---------- loot / advancement / predicate refs ----------
p("\n== RESOURCE REFS ==")
loot_bad = []
for fid in funcs:
    for i, l in code_lines(fid):
        for m in re.finditer(r'\bloot\s+([a-z0-9_.\-]+:[a-z0-9_/.\-]+)', l):
            if m.group(1) not in loot: loot_bad.append((fid, i, m.group(1)))
p("missing loot table refs:", len(loot_bad))
for x in loot_bad[:20]: p("  ", x)

adv_bad = []
for fid in funcs:
    for i, l in code_lines(fid):
        for m in re.finditer(r'\badvancement\s+(?:grant|revoke)\s+\S+\s+(?:only|through|from|everything)\s+([a-z0-9_.\-]+:[a-z0-9_/.\-]+)', l):
            if m.group(1) not in adv_exist: adv_bad.append((fid, i, m.group(1)))
p("missing advancement refs:", len(adv_bad))
for x in adv_bad[:20]: p("  ", x)

pred_bad = []
for fid in funcs:
    for i, l in code_lines(fid):
        for m in re.finditer(r'\bpredicate\s+([a-z0-9_.\-]+:[a-z0-9_/.\-]+)', l):
            if m.group(1) not in pred_exist: pred_bad.append((fid, i, m.group(1)))
p("missing predicate refs:", len(pred_bad))
for x in pred_bad[:20]: p("  ", x)

# storage refs
storages = collections.defaultdict(set)
for fid in funcs:
    for i, l in code_lines(fid):
        for m in re.finditer(r'\bstorage\s+([a-z0-9_.\-]+:[a-z0-9_/.]+)', l):
            storages[m.group(1).split(':')[0]].add(m.group(1))
p("storage namespaces touched:", {k: len(v) for k, v in storages.items()})

# ---------- line lint ----------
p("\n== LINE LINT ==")
lint = []
for fid in funcs:
    txt = text(funcs[fid])
    for i, raw in enumerate(txt.split('\n'), 1):
        l = raw.split('#')[0]
        if not l.strip(): continue
        if l.count('"') % 2: lint.append((fid, i, 'odd quotes', raw.strip()[:110]))
        if l.count('{') != l.count('}'): lint.append((fid, i, 'brace mismatch', raw.strip()[:110]))
        if l.count('[') != l.count(']'): lint.append((fid, i, 'bracket mismatch', raw.strip()[:110]))
        if re.search(r'\b(execute|run|if|unless|as|at|positioned|in|align|anchored|rotated|facing|store|summon)\s*$', l):
            lint.append((fid, i, 'dangling clause', raw.strip()[:110]))
p("lint hits:", len(lint))
for x in lint[:40]: p("  ", x)

# ---------- gamerules & known-bad patterns ----------
p("\n== GAMERULES / BAD PATTERNS ==")
gamerules = set()
for fid in funcs:
    for i, l in code_lines(fid):
        m = re.search(r'\bgamerule\s+(\S+)', l)
        if m: gamerules.add(m.group(1))
p("gamerules used:", sorted(gamerules))
for fid in funcs:
    for i, l in code_lines(fid):
        if 'keep_inventory' in l: p(f"  SNAKE gamerule {fid}:{i}: {l.strip()[:110]}")

# ---------- score constants / state machine ----------
p("\n== STATE / COUNTER WRITES ==")
writes = collections.Counter()
for fid in funcs:
    for i, l in code_lines(fid):
        m = re.search(r'scoreboard\s+players\s+(?:set|add|remove)\s+(\S+)\s+(\S+)\s+(-?\d+)', l)
        if m: writes[(m.group(2), m.group(1), m.group(3))] += 1
for k, v in sorted(writes.items()): p("  ", k, "x", v)

# ---------- pack.mcmeta ----------
p("\n== PACK.MCMETA ==")
p(z.read('pack.mcmeta').decode('utf-8-sig'))

with open(r"_build/obls_lint_report.txt", "w", encoding="utf-8", newline="\n") as f:
    f.write(out.getvalue())
print("WROTE report,", len(out.getvalue()), "bytes")

