"""Audit v2: correct comment handling + JSON text-component validation + full dump of oneblock:*."""
import zipfile, json, re, io, collections

ZIP = r"minecraft-datapacks/OneBlockLastStanding/OneBlockLastStanding.zip"
z = zipfile.ZipFile(ZIP)
names = [n for n in z.namelist() if not n.endswith('/') and not n.startswith('__MACOSX')]
funcs = {}
for n in names:
    m = re.match(r'^data/([^/]+)/function/(.+)\.mcfunction$', n)
    if m:
        funcs[m.group(1) + ":" + m.group(2)] = n

def text(m):
    return z.read(m).decode('utf-8', 'replace').replace('\r\n', '\n')

def is_comment(line):
    return line.lstrip().startswith('#')

def ascii_safe(s):
    return s.encode('unicode_escape').decode('ascii')

rep = io.StringIO()
def p(*a):
    print(*a, file=rep)

# --- 1. balance lint (fixed) ---
p("== BALANCE LINT (comments=full-line only) ==")
lint = []
for fid in funcs:
    for i, raw in enumerate(text(funcs[fid]).split('\n'), 1):
        if is_comment(raw) or not raw.strip():
            continue
        c = raw
        if c.count('"') % 2:
            lint.append((fid, i, 'odd quotes', c[:150]))
        if c.count('{') != c.count('}'):
            lint.append((fid, i, 'brace mismatch', c[:150]))
        if c.count('[') != c.count(']'):
            lint.append((fid, i, 'bracket mismatch', c[:150]))
        if c.count('(') != c.count(')'):
            lint.append((fid, i, 'paren mismatch', c[:150]))
p("hits:", len(lint))
for x in lint[:50]:
    p("  ", x[0] + ":" + str(x[1]), x[2], "|", ascii_safe(x[3]))

# --- 2. JSON text components in title/tellraw ---
p("")
p("== TEXT-COMPONENT JSON VALIDITY ==")
bad_json = []
PAT = re.compile(r'(?:^|\s)(?:tellraw\s+\S+\s+|title\s+\S+\s+(?:title|subtitle|actionbar|fadein|fadeout|stay)\s+)(.*)$')
for fid in funcs:
    for i, raw in enumerate(text(funcs[fid]).split('\n'), 1):
        if is_comment(raw):
            continue
        m = PAT.search(raw)
        if m:
            js = m.group(1).strip()
            # NBT-style dict for title times: skip
            try:
                json.loads(js)
            except Exception as e:
                bad_json.append((fid, i, str(e)[:80], js[:120]))
p("invalid text-component JSON:", len(bad_json))
for x in bad_json[:40]:
    p("  ", x[0] + ":" + str(x[1]), "|", x[2], "|", ascii_safe(x[3]))

# --- 3. execute-chain well-formedness (count subcommand keywords) ---
p("")
p("== EXECUTE CHAINS ==")
EXEC = re.compile(r'^\s*execute\b')
KNOWN = {'run','as','at','positioned','rotated','facing','in','align','if','unless','store','on'}
issues = []
for fid in funcs:
    for i, raw in enumerate(text(funcs[fid]).split('\n'), 1):
        if EXEC.match(raw) and not is_comment(raw):
            # must contain ' run ' with something after
            idx = raw.find(' run ')
            if idx < 0 or not raw[idx+5:].strip():
                issues.append((fid, i, 'execute without run', raw[:120]))
p("issues:", len(issues))
for x in issues[:30]:
    p("  ", x)

# --- 4. dump all oneblock functions ---
p("")
p("== ONEBLOCK SOURCES ==")
for fid in sorted(k for k in funcs if k.startswith('oneblock:')):
    p("#### " + fid)
    for i, raw in enumerate(text(funcs[fid]).split('\n'), 1):
        p("%3d| %s" % (i, ascii_safe(raw)))

