import zipfile, json, re, hashlib, os, collections

ZIP = r"minecraft-datapacks/OneBlockLastStanding/OneBlockLastStanding.zip"
EXT = r"_build/obls_verify"
R = []
def p(*a):
    R.append(" ".join(str(x) for x in a))

z = zipfile.ZipFile(ZIP)
members = {}
nfiles = 0
for n in z.namelist():
    if n.endswith('/') or n.startswith('__MACOSX'):
        continue
    nfiles += 1
    members[n] = hashlib.sha256(z.read(n)).hexdigest()
p("ZIP files:", nfiles)

disk = []
for root, dirs, fs in os.walk(EXT):
    for f in fs:
        full = os.path.join(root, f)
        rel = os.path.relpath(full, EXT).replace('\\', '/')
        disk.append(rel)
missing = [n for n in members if n not in disk]
extra = [d for d in disk if d not in members]
p("extracted:", len(disk), "missing_from_disk:", len(missing), "extra:", len(extra))
if missing: p("  MISSING", missing[:5])
if extra: p("  EXTRA", extra[:5])
mismatch = 0
for rel in disk:
    full = os.path.join(EXT, rel.replace('/', os.sep))
    if rel in members and hashlib.sha256(open(full, 'rb').read()).hexdigest() != members[rel]:
        mismatch += 1
        p("  HASH MISMATCH", rel)
p("hash mismatches:", mismatch)

# ---- text components (JSON after tellraw/title/... ) ----
funcs = {}
for n in members:
    m = re.match(r'^data/([^/]+)/function/(.+)\.mcfunction$', n)
    if m:
        funcs[m.group(1) + ":" + m.group(2)] = n

def lines_of(fid):
