TC = re.compile(r'^(?:execute\b.*?\brun\s+)?(tellraw|title|me|say|msg|w|teammsg|tm)\s+(?:@a|@p|@e|@r|\S+\s)?(?:(?:title|subtitle|actionbar|times|clear|reset)\s+)?(.*)$')
