        m = re.search(r'\b(tellraw|title)\s+(?:\S+\s+)?(?:@a|@p|@r|@e|\S+)?(?:\s+(?:title|subtitle|actionbar|times|clear|reset))?\s+(\[.*)', raw)
        if not m:
            continue
        payload = m.group(2)
        # trim trailing non-json if any
        try:
            json.loads(payload)
            checked += 1
        except Exception as e:
            bad_json.append((fid, i, str(e)[:80], payload[:120]))
p("text components parsed OK:", checked)
p("text component parse errors:", len(bad_json))
for b in bad_json[:20]:
    p("  TC ERR", b)

# ---- per-line SNBT/selector bracket balance (comment = line-leading #) ----
bal = []
for fid in sorted(funcs):
    for i, raw in enumerate(lines_of(fid), 1):
        l = raw
        if l.lstrip().startswith('#'):
            continue
        # strip selector options? They use [ ... ] which must balance too
