for n in names:
    m = re.match(r'^data/([^/]+)/function/(.+)\.mcfunction$', n)
    if m:
        funcs[m.group(1) + ":" + m.group(2)] = n

def text(member):
    return z.read(member).decode('utf-8', 'replace').replace('\r\n', '\n')

def lines_of(fid):
    return text(funcs[fid]).split('\n')

def strip_comment(l):
    s = l.lstrip()
    if s.startswith('#') or s.startswith('//'):
        return ''
    return l.rstrip()

def esc(s):
    return s.encode('unicode_escape').decode('ascii', 'replace')

r = io.StringIO()
def p(*a):
