        l = strip_comment(raw)
        if not l.strip():
            continue
        q = l.count('"') - 2 * l.count('\\"')
        if q % 2:
            lint.append((fid, i, 'odd quotes', esc(l)))
        if l.count('{') != l.count('}'):
            lint.append((fid, i, 'brace mismatch', esc(l)))
        if l.count('[') != l.count(']'):
            lint.append((fid, i, 'bracket mismatch', esc(l)))
