        l = strip_comment(raw)
        if not l.strip():
            continue
        # command ends inside an unterminated quoted string => next line is a continuation (ILLEGAL in mcfunction)
        depth = 0
        insq = None
        j = 0
        while j < len(l):
            c = l[j]
            if insq:
                if c == '\\':
                    j += 2
                    continue
                if c == insq:
                    insq = None
            else:
                if c in '"\'':
                    insq = c
            j += 1
        if insq is not None:
            p("  UNCLOSED STRING", fid, "line", i, "|", esc(l))
        elif l.count('{') != l.count('}'):
