"""Second-pass audit: fixed comment handling, text-component JSON validation,
SNBT balance per line, execute-chain sanity, and full oneblock function dump."""
import zipfile, json, re, collections, io

ZIP = r"minecraft-datapacks/OneBlockLastStanding/OneBlockLastStanding.zip"
z = zipfile.ZipFile(ZIP)
names = [n for n in z.namelist() if not n.endswith('/') and not n.startswith('__MACOSX')]

funcs = {}
for n in names:
    m = re.match(r'^data/([^/]+)/function/(.+)\.mcfunction$', n)
    if m:
        funcs[m.group(1) + ":" + m.group(2)] = n

def text(member):
    return z.read(member).decode('utf-8', 'replace').replace('\r\n', '\n')

def lines(fid):
    return text(funcs[fid]).split('\n')

def is_comment(l):
    return l.lstrip().startswith('#')

rep = io.StringIO()
def p(*a):
    print(*a, file=rep)

# ---------- fixed lint ----------
p("== LINT v2 (correct comment handling) ==")
hits = []
for fid in sorted(funcs):
    for i, raw in enumerate(lines(fid), 1):
        l = raw.rstrip()
        if not l.strip() or is_comment(l):
            continue
        if l.count('"') % 2:
            hits.append((fid, i, 'odd quotes', l))
        if l.count('{') != l.count('}'):
            hits.append((fid, i, 'brace imbalance', l))
        if l.count('[') != l.count(']'):
            hits.append((fid, i, 'bracket imbalance', l))
p("hits:", len(hits))
for fid, i, kind, l in hits:
    p("  " + fid + ":" + str(i) + " " + kind + " | " + l[:200])

# ---------- text component JSON validation ----------
p("")
p("== TEXT COMPONENT JSON ==")
bad_json = []
SEL = r'(?:@[a-z](?:\[[^\]]*\])?|\w+)'
pat_title = re.compile(r'\btitle\s+' + SEL + r'\s+(?:title|subtitle|actionbar)\s+(\{.*\}|\[.*\])\s*$', re.S)
pat_tellraw = re.compile(r'\btellraw\s+' + SEL + r'\s+(\{.*\}|\[.*\])\s*$', re.S)
checked = 0
for fid in sorted(funcs):
    for i, raw in enumerate(lines(fid), 1):
        l = raw.strip()
        if is_comment(l):
            continue
        for pat in (pat_title, pat_tellraw):
            m = pat.search(l)
            if m:
                checked += 1
                frag = m.group(1)
                try:
                    json.loads(frag)
                except Exception as e:
                    bad_json.append((fid, i, str(e), frag[:200]))
p("text components checked:", checked)
p("json parse failures:", len(bad_json))
for fid, i, e, frag in bad_json:
    p("  BAD " + fid + ":" + str(i) + " " + e[:100])
    p("      " + frag)

# ---------- execute chain sanity ----------
p("")
p("== EXECUTE CHAINS ==")
bad_exec = []
for fid in sorted(funcs):
    for i, raw in enumerate(lines(fid), 1):
        l = raw.strip()
        if is_comment(l) or not l.startswith('execute'):
            continue
        if not re.search(r'\brun\s+\S', l):
            bad_exec.append((fid, i, l))
p("execute without run:", len(bad_exec))
for fid, i, l in bad_exec:
    p("  " + fid + ":" + str(i) + " | " + l[:150])

# ---------- title/tellraw selectors sanity ----------
p("")
p("== SELECTOR SANITY ==")
sel_bad = []
for fid in sorted(funcs):
    for i, raw in enumerate(lines(fid), 1):
        l = raw.strip()
        if is_comment(l):
            continue
        for m in re.finditer(r'@(a|e|p|s|r)\[([^\]]*)\]', l):
            body = m.group(2)
            depth = 0
            for ch in body:
                if ch == '{':
                    depth += 1
                elif ch == '}':
                    depth -= 1
                    if depth < 0:
                        sel_bad.append((fid, i, 'neg brace', l[:160]))
                        break
                elif ch == ',' and depth < 0:
                    sel_bad.append((fid, i, 'depth?', l[:160]))
            if m.group(1) in ('p', 'r') and 'count' in body and 'limit' in body:
                sel_bad.append((fid, i, 'count+limit', l[:160]))
seen = set()
uniq = []
for x in sel_bad:
