for fid, i, kind, l in uniq[:30]:
    p("  " + fid + ":" + str(i) + " " + kind + " | " + l)

# ---------- scoreboard operation sanity ----------
p("")
p("== SCORE OPERATIONS ==")
OPS = ('+=', '-=', '*=', '/=', '=%', '<', '>', '<>')
op_bad = []
for fid in sorted(funcs):
    for i, raw in enumerate(lines(fid), 1):
        l = raw.strip()
        if is_comment(l):
            continue
        m = re.search(r'scoreboard\s+players\s+operation\s+(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s+(\S+)', l)
        if m:
            if m.group(3) not in OPS:
                op_bad.append((fid, i, m.group(3), l[:150]))
p("invalid operation tokens:", len(op_bad))
for x in op_bad[:20]:
    p("  ", x)

# ---------- storage writes ----------
p("")
p("== STORAGE REFS ==")
stor = collections.defaultdict(list)
for fid in sorted(funcs):
    for i, raw in enumerate(lines(fid), 1):
        l = raw.strip()
        if is_comment(l):
            continue
        for m in re.finditer(r'data\s+(?:modify|merge|get|remove)\s+storage\s+(\S+)', l):
            stor[m.group(1)].append((fid, i, m.group(0)[:40]))
for k in sorted(stor):
    p("  ", k, len(stor[k]), "refs")
    for fid, i, frag in stor[k][:2]:
        p("      ", fid + ":" + str(i))

# ---------- entity ids ----------
p("")
p("== ENTITY IDs (summon/@e type=) ==")
ent = collections.Counter()
for fid in sorted(funcs):
    t = text(funcs[fid])
    for m in re.finditer(r'summon\s+([a-z0-9_.\-]+:[a-z0-9_]+)', t):
        ent[m.group(1)] += 1
    for m in re.finditer(r'\btype=([a-z0-9_.\-]+:[a-z0-9_]+)', t):
        ent[m.group(1)] += 1
for k in sorted(ent):
    p("  ", k, "x", ent[k])

# ---------- block ids used in setblock/fill ----------
p("")
p("== BLOCK IDS ==")
blks = collections.Counter()
for fid in sorted(funcs):
    t = text(funcs[fid])
    for m in re.finditer(r'(?:setblock|fill)\s+(?:~?-?\d*|~)(?:~~?)?[ ~\-0-9]*?\s+([a-z0-9_.\-]+:[a-z0-9_]+(?:\{[^\n]*)?)', t):
        blks[m.group(1).split('{')[0]] += 1
for k in sorted(blks):
