"""Second-pass audit of OneBlockLastStanding.zip.

Fixes pass-1 false positives (comment '#' only strips at line start).
Adds: SNBT/JSON balance, text-component validation, execute-chain sanity,
objective-criteria sanity, selector-bracket sanity.
Writes ASCII-safe report to _build/r2.txt and oneblock function dump to _build/r2_funcs.txt.
"""
import zipfile, json, re, collections

ZIP = "minecraft-datapacks/OneBlockLastStanding/OneBlockLastStanding.zip"
z = zipfile.ZipFile(ZIP)
names = [n for n in z.namelist() if not n.endswith("/") and not n.startswith("__MACOSX")]
funcs = {}
for n in names:
    m = re.match(r"^data/([^/]+)/function/(.+)\.mcfunction$", n)
    if m:
        funcs[m.group(1) + ":" + m.group(2)] = n

def text(member):
    return z.read(member).decode("utf-8", "replace").replace("\r\n", "\n")

def strip_comment(line):
    s = line.lstrip()
    if s.startswith("#"):
        return ""
    return line

def esc(s):
    return s.encode("ascii", "backslashreplace").decode("ascii")

lines_of = {}
for fid, member in funcs.items():
    lines_of[fid] = text(member).split("\n")

rep = []
def w(s):
    rep.append(s)

# ---------- 1. per-line balance (no comment mangling) ----------
w("== BALANCE / STRUCTURE ==")
hits = 0
for fid in sorted(funcs):
    for i, raw in enumerate(lines_of[fid], 1):
        l = strip_comment(raw)
        if not l.strip():
            continue
        code = l.rstrip()
        problems = []
        if code.count('"') % 2:
            problems.append("odd quotes")
        if code.count("{") != code.count("}"):
            problems.append("brace mismatch")
        if code.count("[") != code.count("]"):
            problems.append("bracket mismatch")
        if code.endswith(" run ") or code.endswith(" run") or re.search(r"\bexecute\s*$", code):
            problems.append("dangling execute")
        if problems:
            hits += 1
            w("  " + fid + ":" + str(i) + " " + ",".join(problems) + " | " + esc(code)[:160])
w("balance hits: " + str(hits))

# ---------- 2. multi-line command continuation detection ----------
# a line ending with an unterminated NBT/JSON object, where next line is not a command start
w("")
w("== SUSPECTED BROKEN CONTINUATIONS ==")
CMDSTART = re.compile(r"^(execute|function|scoreboard|data|setblock|fill|clone|tp|teleport|summon|effect|give|clear|kill|title|tellraw|say|msg|team|tag|bossbar|schedule|gamerule|time|weather|stop|xp|enchant|repair|replace|item|loot|trigger|spreadplayers|playsound|stopsound|particle|damage|ride|dialog|place)\b")
cont = 0
for fid in sorted(funcs):
    ls = lines_of[fid]
    for i, raw in enumerate(ls):
        l = strip_comment(raw)
        if not l.strip():
            continue
        code = l.rstrip()
        unbalanced = code.count("{") != code.count("}") or code.count('"') % 2
        if unbalanced and i + 1 < len(ls):
            nxt = strip_comment(ls[i + 1]).strip()
            if nxt and not CMDSTART.match(nxt):
                cont += 1
                w("  " + fid + ":" + str(i + 1) + " -> next line not a command | " + esc(code)[:120] + " ||| " + esc(nxt)[:80])
w("continuation suspects: " + str(cont))

# ---------- 3. text components (title/tellraw JSON) ----------
w("")
w("== TEXT COMPONENT JSON ==")
tc_checked = 0
tc_bad = 0
for fid in sorted(funcs):
    for i, raw in enumerate(lines_of[fid], 1):
        l = strip_comment(raw).strip()
        m = re.match(r"^(?:[a-z_ ]*?run\s+)?(tellraw|title)\s+(\S+)\s+(?:title|subtitle|actionbar)\s+(\[.*)$", l) if l.startswith("title") else re.match(r"^(tellraw)\s+(\S+)\s+(\[.*)$", l)
        if not m:
            continue
        payload = m.group(3)
        tc_checked += 1
        try:
            json.loads(payload)
        except Exception as e:
            tc_bad += 1
            w("  JSON FAIL " + fid + ":" + str(i) + " | " + esc(str(e))[:90] + " | " + esc(payload)[:140])
w("text components checked: " + str(tc_checked) + ", invalid: " + str(tc_bad))

# ---------- 4. scoreboard objectives: created vs used (proper comment strip) ----------
w("")
w("== OBJECTIVES v2 ==")
created = {}
used = collections.defaultdict(list)
for fid in sorted(funcs):
    for i, raw in enumerate(lines_of[fid], 1):
        l = strip_comment(raw).strip()
        m = re.search(r"\bscoreboard\s+objectives\s+add\s+(\S+)(\s+\S+)?", l)
        if m:
            created[m.group(1)] = (m.group(2) or "").strip()
        m = re.search(r"\bscoreboard\s+players\s+(set|add|remove|get|reset|enable|operation|random|test)\s+(.*)", l)
        if m:
            rest = m.group(2).split()
            op = m.group(1)
            if op == "operation":
                if len(rest) >= 5:
                    used[rest[1]].append((fid, i, l))
                    used[rest[4]].append((fid, i, l))
                    if rest[2] not in ("=", "+=", "-=", "*=", "/=", "%=", "<", ">", "<>"):
                        w("  BAD OPERATION " + fid + ":" + str(i) + " | " + esc(l)[:140])
            elif len(rest) >= 2:
                used[rest[1]].append((fid, i, l))
        m = re.search(r"\bscoreboard\s+objectives\s+setdisplay\s+(sidebar|list|belowName|sidebar\.team\.\w+)\s*(\S*)", l)
        if m and m.group(2) and m.group(2) not in created:
            used[m.group(2)].append((fid, i, l))
w("created: " + json.dumps({k: v for k, v in sorted(created.items())}))
never = sorted(set(used) - set(created))
w("used but never created: " + str(never))
for o in never:
    for fid, i, l in used[o][:3]:
        w("  " + o + " <- " + fid + ":" + str(i) + " | " + esc(l)[:130])

# ---------- 5. function calls v2 ----------
w("")
w("== CALLS v2 ==")
CALL = re.compile(r"\bfunction\s+([a-z0-9_.\-]+):([a-z0-9_/.\-]+)")
bad = 0
for fid in sorted(funcs):
    for i, raw in enumerate(lines_of[fid], 1):
        l = strip_comment(raw)
        for m in CALL.finditer(l):
            ref = m.group(1) + ":" + m.group(2)
            if ref not in funcs:
                bad += 1
                w("  MISSING " + fid + ":" + str(i) + " -> " + ref)
w("dangling calls v2: " + str(bad))

# ---------- 6. gamerules v2 + suspicious patterns ----------
w("")
w("== GAMERULES v2 ==")
gr = collections.defaultdict(list)
for fid in sorted(funcs):
    for i, raw in enumerate(lines_of[fid], 1):
        l = strip_comment(raw)
        for m in re.finditer(r"\bgamerule\s+([a-zA-Z_:]+)", l):
            gr[m.group(1)].append((fid, i))
for k in sorted(gr):
    w("  " + k + " x" + str(len(gr[k])))

# ---------- 7. dump oneblock functions ----------
dump = []
for fid in sorted(funcs):
    if not fid.startswith("oneblock:"):
        continue
    dump.append("##### " + fid + " (" + str(len([1 for x in lines_of[fid] if x.strip()])) + " lines)")
    for i, raw in enumerate(lines_of[fid], 1):
        dump.append(("%4d | " % i) + raw)
open("_build/r2_funcs.txt", "w", encoding="utf-8", newline="\n").write("\n".join(dump))

open("_build/r2.txt", "w", encoding="ascii", newline="\n").write("\n".join(rep))
print("OK r2.txt", sum(len(s) for s in rep), "bytes; funcs", len("\n".join(dump)), "bytes")

