"""Extract the real command surface of OneBlockLastStanding.zip.

Prints/writes:
  - every oneblock:* function (the supported + internal entry points)
  - tag wiring (what runs on load / tick)
  - trigger objectives + click_event run_command strings (player-facing)
  - config score holders the pack reads/writes with defaults
Writes _build/obls_cmd_inventory.txt
"""
import zipfile, re, json

ZIP = "minecraft-datapacks/OneBlockLastStanding/OneBlockLastStanding.zip"
z = zipfile.ZipFile(ZIP)
names = [n for n in z.namelist() if not n.endswith("/") and not n.startswith("__MACOSX")]

funcs = {}
for n in names:
    m = re.match(r"^data/([^/]+)/function/(.+)\.mcfunction$", n)
    if m:
        funcs[m.group(1) + ":" + m.group(2)] = n

def text(member):
    return z.read(member).decode("utf-8", "replace").replace("\r\n", "\n")

out = []
def w(s=""):
    out.append(s)

ob = sorted(k for k in funcs if k.startswith("oneblock:"))
w("# ONEBLOCK FUNCTIONS (%d)" % len(ob))
for fid in ob:
    n_lines = len([1 for x in text(funcs[fid]).split("\n") if x.strip()])
    w("  %-42s %3d lines" % (fid, n_lines))

w("")
w("# TAG WIRING")
for n in names:
    if n.startswith("data/minecraft/tags/function/"):
        data = json.loads(z.read(n).decode("utf-8-sig"))
        w("  %s -> %s" % (n, data.get("values")))

w("")
w("# TRIGGER OBJECTIVES DEFINED")
for fid in sorted(funcs):
    for i, line in enumerate(text(funcs[fid]).split("\n"), 1):
        if re.search(r"objectives\s+add\s+\S+\s+trigger", line):
            w("  %s:%d  %s" % (fid, i, line.strip()))

w("")
w("# PLAYER-FACING click_event run_command (from oneblock:* only)")
for fid in ob:
    for i, line in enumerate(text(funcs[fid]).split("\n"), 1):
        for m in re.finditer(r'command:"([^"]+)"', line):
            w("  %s:%d  %s" % (fid, i, m.group(1)))

w("")
w("# CLICK EVENTS IN ija-one-block MENUS (upstream, for reference)")
seen = set()
for fid in sorted(funcs):
    if fid.startswith("oneblock:") or "/menu/" not in fid:
        continue
    for m in re.finditer(r'command:"([^"]+)"', text(funcs[fid])):
        if m.group(1) not in seen:
            seen.add(m.group(1))
for c in sorted(seen):
    w("  " + c)

w("")
w("# CONFIG SCORE HOLDERS (defaults + read sites)")
for fid in sorted(funcs):
    for i, line in enumerate(text(funcs[fid]).split("\n"), 1):
        if re.search(r"#(dist|dm_minutes|dm_ticks|1200|250|40|36000|game|lobby|radius|n|alive|left|warn)\b", line):
            w("  %s:%d  %s" % (fid, i, line.strip()[:150]))

txt = "\n".join(out)
open("_build/obls_cmd_inventory.txt", "w", encoding="utf-8", newline="\n").write(txt)
print("OK inventory bytes=%d oneblock_funcs=%d" % (len(txt), len(ob)))

"""Print structure (headings + version lines) of the two spec files, ASCII-safe."""
import os

TARGETS = [
    "minecraft-datapacks/spec/SPECIFICATIONS.md",
    "minecraft-datapacks/OneBlockLastStanding/SPEC.md",
]

for p in TARGETS:
    print("FILE", p, "exists", os.path.exists(p), "size", os.path.getsize(p) if os.path.exists(p) else 0)
    if not os.path.exists(p):
        continue
    txt = open(p, encoding="utf-8", errors="replace").read().replace("\r\n", "\n")
    lines = txt.split("\n")
    print("  lines", len(lines))
    for i, line in enumerate(lines, 1):
        s = line.rstrip()
        if s.startswith("#") or "SPEC_VERSION" in s or "VERSION" in s.upper():
            print("  %4d| %s" % (i, s.encode("ascii", "backslashreplace").decode("ascii")))
    print("  ...last 5 lines:")
    for i, line in enumerate(lines[-5:], len(lines) - 4):
        print("  %4d| %s" % (i, line.encode("ascii", "backslashreplace").decode("ascii")))

