arguments.content:
"""Dev folder clutter analysis + cleanup.

Phase A (default): classify everything, change nothing.
Phase B (--apply): perform the deletions/moves that Phase A proved safe.

Safety rule: a scratch pack-extraction is deleted ONLY if its pack files are
byte-identical to the shipped ZIP (i.e. it is a redundant copy). Anything that
differs is preserved, because it may be the pristine upstream pack.
"""
import os, sys, zipfile, hashlib, shutil, json

DEV = "."
ZIP = "minecraft-datapacks/OneBlockLastStanding/OneBlockLastStanding.zip"
TOOLS = "minecraft-datapacks/_tooling"
APPLY = "--apply" in sys.argv

PACK_EXTS = (".mcfunction", ".json", ".mcmeta")

# scratch dirs left by previous sessions
CANDIDATES = [
    "obls_scratch", "obls_probe", "obls_x", "_obls_x", "_obls_audit", "_snap",
    "_build/obls_extract", "_build/obls_src", "_build/obls_x", "$env:TEMP",
]

# files that are pure dump output
JUNK_FILES = [
    "_snap.zip", "obls_members.txt", "_ob_probe.txt",
    "_build/obls_members.txt", "_build/obls_dump.txt",
]

JUNK_DIRS = ["_build/legacy_tts_media"]

KEEP_TOP = {"minecraft-datapacks"}


def zip_sig():
    z = zipfile.ZipFile(ZIP)
    sig = {}
    for n in z.namelist():
        if n.endswith("/") or n.startswith("__MACOSX"):
            continue
        if n.endswith(PACK_EXTS):
            sig[n] = hashlib.sha256(z.read(n)).hexdigest()
    return sig


def dir_sig(root):
    sig = {}
    for r, ds, fs in os.walk(root):
        for f in fs:
            p = os.path.join(r, f)
            rel = os.path.relpath(p, root).replace("\\", "/")
            if rel.endswith(PACK_EXTS):
                with open(p, "rb") as fh:
                    sig[rel] = hashlib.sha256(fh.read()).hexdigest()
    return sig


def dir_size(root):
    t = n = 0
    for r, ds, fs in os.walk(root):
        for f in fs:
            try:
                t += os.path.getsize(os.path.join(r, f))
                n += 1
            except OSError:
                pass
    return t, n


def rm(path):
    if os.path.isdir(path) and not os.path.islink(path):
        shutil.rmtree(path, ignore_errors=True)
    elif os.path.exists(path):
        os.remove(path)


print("ZIP signature files:", len(zip_sig()))
zsig = zip_sig()
cache = {}
for c in CANDIDATES:
    if not os.path.isdir(c):
        print("absent  ", c)
        continue
    s = dir_sig(c)
    exact = [k for k in s if k in zsig and zsig[k] == s[k]]
    diff = [k for k in s if k in zsig and zsig[k] != s[k]]
    only_here = [k for k in s if k not in zsig]
    zonly = [k for k in zsig if k not in s]
    sz, nf = dir_size(c)
    verdict = "IDENTICAL(copy)" if (not diff and not only_here and not zonly) else "DIFFERS"
    cache[c] = verdict
    print("%-22s %8d B %5d files  match=%d diff=%d only_here=%d missing=%d  -> %s"
          % (c, sz, nf, len(exact), len(diff), len(only_here), len(zonly), verdict))

print()
print("--- junk files ---")
for f in JUNK_FILES:
    if os.path.exists(f):
        print("  %-28s %10d B" % (f, os.path.getsize(f)))
    else:
        print("  %-28s absent" % f)

print("--- junk dirs ---")
for d in JUNK_DIRS:
    if os.path.isdir(d):
        sz, nf = dir_size(d)
        print("  %-28s %10d B %5d files" % (d, sz, nf))
    else:
        print("  %-28s absent" % d)

print()
print("--- Dev top-level inventory (unclassified) ---")
for e in sorted(os.listdir(DEV)):
    if e.startswith(".git") or e == "minecraft-datapacks":
        continue
    p = os.path.join(DEV, e)
    if os.path.isdir(p):
        sz, nf = dir_size(p)
        print("  DIR  %-30s %10d B %5d files" % (e, sz, nf))
    else:
        print("  FILE %-30s %10d B" % (e, os.path.getsize(p)))

if not APPLY:
    print()
    print("DRY RUN - nothing changed. Re-run with --apply to execute.")
    sys.exit(0)

print()
print("--- APPLYING ---")
moved = 0
for c, verdict in cache.items():
    if verdict == "IDENTICAL(copy)":
        rm(c)
        print("  deleted redundant extraction:", c)
    else:
        print("  KEPT (content differs, may be upstream):", c)

for f in JUNK_FILES:
    if os.path.exists(f):
        rm(f)
        print("  deleted junk file:", f)
for d in JUNK_DIRS:
    if os.path.isdir(d):
        rm(d)
        print("  deleted junk dir:", d)

# move audit tooling next to the project
os.makedirs(TOOLS, exist_ok=True)
if os.path.isdir("_build"):
    for f in sorted(os.listdir("_build")):
        if f.endswith(".py"):
            src = os.path.join("_build", f)
            dst = os.path.join(TOOLS, f)
            if os.path.exists(dst):
                os.remove(dst)
            shutil.move(src, dst)
            moved += 1
print("  moved %d tool scripts -> %s" % (moved, TOOLS))

print()
print("--- REMAINING _build ---")
if os.path.isdir("_build"):
    for e in sorted(os.listdir("_build")):
        print("  ", e)
else:
    print("  _build gone")

"""Dev cleanup pass 2: ASCII-safe listing + verified-only deletion.

Deletes a scratch extraction ONLY when it is byte-identical to the shipped ZIP.
Keeps anything that differs (may be upstream). Never touches unclassified entries.
"""
import os, sys, zipfile, hashlib, shutil

DEV = "."
ZIP = "minecraft-datapacks/OneBlockLastStanding/OneBlockLastStanding.zip"
TOOLS = "minecraft-datapacks/_tooling"
APPLY = "--apply" in sys.argv
PACK_EXTS = (".mcfunction", ".json", ".mcmeta")


def esc(s):
    return str(s).encode("ascii", "backslashreplace").decode("ascii")


def zip_sig():
    z = zipfile.ZipFile(ZIP)
    return {n: hashlib.sha256(z.read(n)).hexdigest()
            for n in z.namelist()
            if not n.endswith("/") and not n.startswith("__MACOSX") and n.endswith(PACK_EXTS)}


def dir_sig(root):
    sig = {}
    for r, ds, fs in os.walk(root):
        for f in fs:
            rel = os.path.relpath(os.path.join(r, f), root).replace("\\", "/")
            if rel.endswith(PACK_EXTS):
                with open(os.path.join(r, f), "rb") as fh:
                    sig[rel] = hashlib.sha256(fh.read()).hexdigest()
    return sig


def stats(root):
    t = n = 0
    for r, ds, fs in os.walk(root):
        for f in fs:
            try:
                t += os.path.getsize(os.path.join(r, f))
                n += 1
            except OSError:
                pass
    return t, n


CANDIDATES = [
    "obls_scratch", "obls_probe", "obls_x", "_obls_x", "_obls_audit", "_snap",
    "_build/obls_extract", "_build/obls_src", "_build/obls_x", "$env:TEMP",
]
JUNK_FILES = [
    "_snap.zip", "obls_members.txt", "_ob_probe.txt",
    "_build/obls_members.txt", "_build/obls_dump.txt",
]
JUNK_DIRS = ["_build/legacy_tts_media"]

zsig = zip_sig()
print("ZIP pack files:", len(zsig))
print()
print("== CANDIDATE EXTRACTIONS ==")
redundant, keep = [], []
for c in CANDIDATES:
    if not os.path.isdir(c):
        print("  absent   " + esc(c))
        continue
    s = dir_sig(c)
    sz, nf = stats(c)
    identical = (s and not [k for k in s if zsig.get(k) != s[k]] and not [k for k in s if k not in zsig])
    print("  %-22s %9d B %5d files -> %s" % (esc(c), sz, nf, "IDENTICAL(copy)" if identical else "DIFFERS"))
    (redundant if identical else keep).append(c)

print()
print("== JUNK ==")
for f in JUNK_FILES:
    print("  %-26s %s" % (esc(f), ("%d B" % os.path.getsize(f)) if os.path.exists(f) else "absent"))
for d in JUNK_DIRS:
    print("  %-26s %s" % (esc(d), ("dir, %d files" % stats(d)[1]) if os.path.isdir(d) else "absent"))

print()
print("== DEV TOP LEVEL ==")
rows = []
for e in sorted(os.listdir(DEV)):
    if e.startswith(".git"):
        continue
    p = os.path.join(DEV, e)
    if os.path.isdir(p):
        sz, nf = stats(p)
        rows.append("  DIR  %-34s %10d B %5d files" % (esc(e), sz, nf))
    else:
        rows.append("  FILE %-34s %10d B" % (esc(e), os.path.getsize(p)))
print("\n".join(rows))

if not APPLY:
    print()
    print("DRY RUN - nothing changed. Re-run with --apply.")
    sys.exit(0)

print()
print("== APPLYING ==")
for c in redundant:
    shutil.rmtree(c, ignore_errors=True)
    print("  deleted redundant extraction: " + esc(c))
for c in keep:
    print("  KEPT (differs, may be upstream): " + esc(c))
for f in JUNK_FILES:
    if os.path.exists(f):
        os.remove(f)
        print("  deleted junk file: " + esc(f))
for d in JUNK_DIRS:
    if os.path.isdir(d) and stats(d)[1] == 0:
        os.rmdir(d)
        print("  deleted empty dir: " + esc(d))
    elif os.path.isdir(d):
        print("  KEPT non-empty dir: " + esc(d))

os.makedirs(TOOLS, exist_ok=True)
moved = 0
if os.path.isdir("_build"):
    for f in sorted(os.listdir("_build")):
        if f.endswith(".py"):
            dst = os.path.join(TOOLS, f)
            if os.path.exists(dst):
                os.remove(dst)
            shutil.move(os.path.join("_build", f), dst)
            moved += 1
print("  moved %d scripts -> %s" % (moved, TOOLS))

print()
print("== REMAINING ==")
for e in sorted(os.listdir(DEV)):
    if e.startswith(".git"):
        continue
    print("  " + esc(e))
if os.path.isdir("_build"):
    print("  _build still contains:")
    for e in sorted(os.listdir("_build")):
        print("     " + esc(e))
else:
    print("  _build removed")

"""Dev cleanup pass 3: classify EVERY top-level entry, delete only verified duplicates.

Only directories whose pack files are byte-identical to the shipped ZIP are removed.
Unrelated projects and anything unrecognised are listed, never touched.
"""
import os, sys, zipfile, hashlib, shutil

DEV = "."
ZIP = "minecraft-datapacks/OneBlockLastStanding/OneBlockLastStanding.zip"
KEEP = {"minecraft-datapacks"}
APPLY = "--apply" in sys.argv
PACK_EXTS = (".mcfunction", ".json", ".mcmeta")
MAX_WALK = 1500


def esc(s):
    return str(s).encode("ascii", "backslashreplace").decode("ascii")


def walk_capped(root):
    """(total_bytes, file_count, sig_dict) - sig only if file count is small."""
    total = count = 0
    sig = {}
    for r, ds, fs in os.walk(root):
        for f in fs:
            try:
                total += os.path.getsize(os.path.join(r, f))
            except OSError:
                pass
            count += 1
            if count <= MAX_WALK:
                rel = os.path.relpath(os.path.join(r, f), root).replace("\\", "/")
                if rel.endswith(PACK_EXTS):
                    try:
                        with open(os.path.join(r, f), "rb") as fh:
                            sig[rel] = hashlib.sha256(fh.read()).hexdigest()
                    except OSError:
                        pass
        if count > MAX_WALK:
            return total, count, {}
    return total, count, sig


z = zipfile.ZipFile(ZIP)
zsig = {n: hashlib.sha256(z.read(n)).hexdigest()
        for n in z.namelist()
        if not n.endswith("/") and not n.startswith("__MACOSX") and n.endswith(PACK_EXTS)}
print("ZIP pack files:", len(zsig))

dupes, others, junkdirs = [], [], []
for e in sorted(os.listdir(DEV)):
    p = os.path.join(DEV, e)
    if not os.path.isdir(p) or e.startswith(".git") or e in KEEP:
        continue
    total, count, sig = walk_capped(p)
    if sig and not [k for k in sig if zsig.get(k) != sig[k]] and not [k for k in sig if k not in zsig]:
        dupes.append((e, total, count))
    elif count == 0:
        junkdirs.append((e, total, count))
    else:
        others.append((e, total, count))

print()
print("== DATAPACK DUPLICATES (byte-identical to ZIP) ==")
for e, t, c in dupes:
    print("  %-22s %9d B %5d files" % (esc(e), t, c))
print("  count=%d  bytes=%d" % (len(dupes), sum(t for _, t, _ in dupes)))

print()
print("== EMPTY DIRS ==")
for e, t, c in junkdirs:
    print("  " + esc(e))

print()
print("== OTHER (never touched) ==")
for e, t, c in sorted(others, key=lambda x: -x[1]):
    print("  %-22s %12d B %6d files" % (esc(e), t, c))

if not APPLY:
    print()
    print("DRY RUN. Re-run with --apply.")
    sys.exit(0)

print()
print("== APPLYING ==")
freed = 0
for e, t, c in dupes:
    shutil.rmtree(e, ignore_errors=True)
    freed += t
    print("  deleted duplicate extraction: " + esc(e))
for e, t, c in junkdirs:
    try:
        os.rmdir(e)
        print("  removed empty dir: " + esc(e))
    except OSError as ex:
        print("  could not remove empty dir: " + esc(e) + " (" + esc(ex) + ")")
print("  bytes freed: %d" % freed)

left = [e for e in sorted(os.listdir(DEV)) if not e.startswith(".git")]
print()
print("== REMAINING TOP LEVEL ==")
print("  " + " | ".join(esc(e) for e in left))

"""Sweep every datapack extraction in the workspace and delete ONLY byte-identical copies.

A directory is treated as a datapack copy when it directly contains both `pack.mcmeta`
and `data/`. It is deleted only when, for every file it holds, the same relative path
exists inside OneBlockLastStanding.zip with identical bytes, AND the ZIP contributes no
file that the directory lacks. Anything else is reported and preserved, since it may be
a pristine upstream tree that the audit still needs.
"""
import hashlib
import os
import shutil
import zipfile

ZIP = "minecraft-datapacks/OneBlockLastStanding/OneBlockLastStanding.zip"
KEEP = os.path.normpath("minecraft-datapacks/OneBlockLastStanding")

z = zipfile.ZipFile(ZIP)
zmap = {}
for info in z.infolist():
    if info.is_dir():
        continue
    rel = info.filename.replace("\\", "/")
    zmap[rel] = hashlib.sha256(z.read(info.filename)).hexdigest()
print("zip: %s files=%d" % (ZIP, len(zmap)))


def pack_dirs(base):
    found = []
    for dirpath, dirnames, filenames in os.walk(base):
        dirnames[:] = [d for d in dirnames if d not in (".git", "__MACOSX")]
        names = set(filenames) | set(dirnames)
        if "pack.mcmeta" in names and "data" in names:
            found.append(dirpath)
            dirnames[:] = []
    return found


def audit(root):
    """Return (clean, n_files, diffs, extra, missing)."""
    diffs, extra, n = [], [], 0
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in (".git", "__MACOSX")]
        for fn in filenames:
            fp = os.path.join(dirpath, fn)
            rel = os.path.relpath(fp, root).replace("\\", "/")
            n += 1
            if rel not in zmap:
                extra.append(rel)
                continue
            with open(fp, "rb") as fh:
                if hashlib.sha256(fh.read()).hexdigest() != zmap[rel]:
                    diffs.append(rel)
    missing = [p for p in zmap if not os.path.exists(os.path.join(root, p))]
    return (n, diffs, extra, missing)


candidates = []
for base in ("minecraft-datapacks", "."):
    for d in pack_dirs(base):
        if os.path.normpath(d) == KEEP or os.path.normpath(d) in candidates:
            continue
        if os.path.normpath(d).startswith(KEEP + os.sep):
            candidates.append(os.path.normpath(d))
        elif base == "minecraft-datapacks":
            candidates.append(os.path.normpath(d))

print()
print("== DATAPACK COPIES FOUND: %d ==" % len(candidates))
removable = []
for d in candidates:
    n, diffs, extra, missing = audit(d)
    if not diffs and not extra and not missing:
        removable.append(d)
        print("  IDENTICAL  %-62s files=%d" % (d, n))
    else:
        print("  DIFFERS    %-62s files=%d diffs=%d extra=%d missing=%d"
              % (d, n, len(diffs), len(extra), len(missing)))
        for label, items in (("differ", diffs), ("extra", extra), ("missing", missing)):
            for it in items[:8]:
                print("               %-7s %s" % (label, it))
            if len(items) > 8:
                print("               %-7s ... +%d more" % (label, len(items) - 8))

print()
print("== APPLYING ==")
freed = 0
for d in removable:
    for dirpath, _, filenames in os.walk(d):
        for fn in filenames:
            freed += os.path.getsize(os.path.join(dirpath, fn))
    shutil.rmtree(d)
    print("  removed %s" % d)
print("  freed %d bytes" % freed)

# Empty shell: the malformed PowerShell-artifact directory.
for e in sorted(os.listdir(".")):
    p = os.path.join(".", e)
    if os.path.isdir(p) and (e.startswith("$env") or "\uf03a" in e):
        shutil.rmtree(p)
        print("  removed malformed dir %r" % e)

print()
print("== REMAINING ==")
print("  minecraft-datapacks/: " + " | ".join(sorted(os.listdir("minecraft-datapacks"))))
print("  pack folder: " + " | ".join(sorted(os.listdir(KEEP))))

